const fs=require('node:fs'),path=require('node:path'),http=require('node:http'),assert=require('node:assert/strict');
const {chromium}=require('playwright');
const root=path.resolve(__dirname,'..'),rows=require('./career-comparison-20261104.cjs');
const server=http.createServer((req,res)=>{let file=path.resolve(root,'.'+decodeURI(new URL(req.url,'http://local').pathname));if(file!==root&&!file.startsWith(root+path.sep))return res.writeHead(403).end();if(fs.existsSync(file)&&fs.statSync(file).isDirectory())file=path.join(file,'index.html');if(!fs.existsSync(file))return res.writeHead(404).end();res.writeHead(200,{'Content-Type':({'.html':'text/html; charset=utf-8','.css':'text/css','.js':'application/javascript','.json':'application/json','.webp':'image/webp','.png':'image/png','.csv':'text/csv; charset=utf-8'})[path.extname(file)]||'application/octet-stream'});fs.createReadStream(file).pipe(res);});
async function run(){if(!process.env.TEST_ORIGIN)await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin=process.env.TEST_ORIGIN||`http://127.0.0.1:${server.address().port}`,browser=await chromium.launch(),output=path.resolve(root,'../4050-career-comparison-20261104'+(process.env.TEST_ORIGIN?'-live':''));fs.mkdirSync(output,{recursive:true});try{
 const p=await browser.newPage(),errors=[],ads=[],assetErrors=[];p.on('pageerror',e=>errors.push(e.message));p.on('response',r=>{if(r.url().startsWith(origin)&&/\.(css|js|png|webp)(?:[?_]|$)/.test(r.url())&&r.status()>=400)assetErrors.push(r.url());});await p.route('**/*',r=>{if(/googlesyndication|doubleclick|googleadservices/.test(r.request().url()))ads.push(r.request().url());return r.request().url().startsWith(origin)?r.continue():r.abort();});
 const route='/재취업-직무-비교/';
 for(const width of [1440,1280,768,390,320]){await p.setViewportSize({width,height:900});assert.equal((await p.goto(origin+route)).status(),200);await p.locator('#compare-conditions fieldset:not([disabled])').waitFor();assert.equal(await p.locator('tbody tr').count(),4);assert.equal(await p.locator('link[rel="canonical"]').getAttribute('href'),'https://4050guide.co.kr'+route);assert.equal(await p.locator('main h1').count(),1);
  for(const im of await p.locator('.compare-photo-row img').all()){await im.evaluate(n=>n.decode());assert.ok(await im.evaluate(n=>n.naturalWidth>0));}
  const scroll=p.locator('.compare-scroll');if(width<1030){await scroll.focus();await p.keyboard.press('ArrowRight');await p.waitForTimeout(200);assert.ok(await scroll.evaluate(n=>n.scrollLeft>0));await scroll.evaluate(n=>{n.scrollLeft=0});}
  assert.equal(await p.locator('.brand').evaluate(n=>getComputedStyle(n).textDecorationLine),'none');
  assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false,'overflow '+width);
  await p.evaluate(()=>scrollTo(0,0));await p.screenshot({path:path.join(output,'first-'+width+'.png')});await p.screenshot({path:path.join(output,'full-'+width+'.png'),fullPage:true});
 }
 const keys=['night','commute','cost'];for(let mask=0;mask<8;mask++){for(let i=0;i<keys.length;i++)await p.locator('input[value="'+keys[i]+'"]').setChecked(Boolean(mask&(1<<i)));const selected=keys.filter((_,i)=>mask&(1<<i));for(const row of rows)assert.deepEqual(await p.locator('[data-result="'+row.id+'"] ul li').allTextContents(),selected.length?selected.map(key=>row.notes[key]):[row.base]);}
 await p.getByRole('button',{name:'조건 선택 초기화',exact:true}).click();assert.equal(await p.locator('input:checked').count(),0);await p.locator('input[value="night"]').focus();await p.keyboard.press('Space');assert.equal(await p.locator('input[value="night"]').isChecked(),true);await p.reload();assert.equal(await p.locator('input:checked').count(),0);
 const hrefs=await p.locator('main a[href]').evaluateAll(nodes=>[...new Set(nodes.map(n=>n.getAttribute('href')).filter(h=>h.startsWith('/')))]);for(const href of hrefs)assert.equal((await p.request.get(origin+encodeURI(href))).status(),200,href);
 const download=p.waitForEvent('download');await p.locator('.compare-entry-links a[download]').click();const d=await download;assert.equal(d.suggestedFilename(),'career-comparison-20261104.csv');const saved=path.join(output,d.suggestedFilename());await d.saveAs(saved);const csv=fs.readFileSync(saved,'utf8');assert.ok(csv.startsWith('\uFEFF'));assert.ok(csv.includes('공고에 추가 확인할 내용'));for(const row of rows)assert.ok(csv.includes(row.name));assert.equal(csv.trimEnd().split('\r\n').length,7);
 await p.locator('.compare-sources summary').click();assert.match(await p.locator('.compare-sources').innerText(),/J10 원문은 재열람되지 않아/);assert.equal(await p.locator('script[src*="home-ads.js"]').count(),0);assert.deepEqual(ads,[]);assert.deepEqual(errors,[]);assert.deepEqual(assetErrors,[]);
 const c=await browser.newContext({javaScriptEnabled:false}),n=await c.newPage();await n.goto(origin+route);assert.equal(await n.locator('tbody tr').count(),4);assert.equal(await n.locator('.compare-results>li').count(),4);assert.equal(await n.locator('#compare-conditions input').first().isDisabled(),true);assert.ok(await n.locator('a[download]').first().isVisible());await c.close();
 const comparisonAdRequests=ads.length;await p.goto(origin+'/');assert.ok(await p.locator('.career-section-heading a[href="'+route+'"]').isVisible());await p.locator('.career-section-heading a').click();await p.locator('[data-career-comparison]').waitFor();
 const report={pass:true,origin,widths:[1440,1280,768,390,320],jobRows:4,conditionCombinations:8,keyboardCheckbox:true,keyboardTableScroll:true,noJsFallback:true,noStoredConditions:true,csvDownload:true,checkedInternalLinks:hrefs.length,adRequests:comparisonAdRequests,assetErrors:assetErrors.length,output};fs.writeFileSync(path.join(root,'reports/career-comparison-qa'+(process.env.TEST_ORIGIN?'-live':'')+'-20261104.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report));
 }finally{await browser.close();server.close();}}
run().catch(e=>{console.error(e);server.close();process.exitCode=1});
